const govValues = `-- name: GovValues :many
SELECT scope_key,config_key,value_json FROM gov_values WHERE tenant_id=$1 AND scope_key=ANY($2::text[]) ORDER BY scope_key,config_key
`

type GovValuesParams struct {
	TenantID string
	Column2  []string
}

type GovValuesRow struct {
	ScopeKey  string
	ConfigKey string
	ValueJson []byte
}

func (q *Queries) GovValues(ctx context.Context, arg GovValuesParams) ([]GovValuesRow, error) {
	rows, err := q.db.Query(ctx, govValues, arg.TenantID, arg.Column2)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GovValuesRow{}
	for rows.Next() {
		var i GovValuesRow
		if err := rows.Scan(&i.ScopeKey, &i.ConfigKey, &i.ValueJson); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

